$base = "http://localhost:8091"
$h = @{ 'zhi-project-id' = 'suzhufang' }
$jar = $null
for ($i=1; $i -le 4; $i++) {
  try {
    $req = [System.Net.HttpWebRequest]::Create($base + "/api/v3.0/portal/appLogin/captcha")
    $req.Method = 'POST'; $req.ContentType='application/json'; $req.Timeout=10000
    $req.Headers.Add('zhi-project-id','suzhufang')
    if ($jar) { $req.Headers.Add('Cookie', $jar) }
    $reqBody = [System.Text.Encoding]::UTF8.GetBytes('{}')
    $req.GetRequestStream().Write($reqBody,0,$reqBody.Length)
    $resp = $req.GetResponse()
    $cookies = $resp.Headers['Set-Cookie']
    if ($cookies) { $jar = $cookies }
    $sr = New-Object System.IO.StreamReader($resp.GetResponseStream())
    $txt = $sr.ReadToEnd(); $sr.Close(); $resp.Close()
    $json = $txt | ConvertFrom-Json
    if ($json.code -eq 200 -and $json.data.img) {
      $img = $json.data.img
      $pfx="data:image/png;base64,"
      $b64 = if($img.StartsWith($pfx)){$img.Substring($pfx.Length)}else{$img}
      [System.IO.File]::WriteAllBytes("D:\repository\门户H5\captcha.png", [System.Convert]::FromBase64String($b64))
      "OK attempt $i | uuid=$($json.data.uuid) | cookie=$(if($jar){'yes'}else{'no'}) | saved captcha.png"
      break
    } else { "attempt $i => code=$($json.code) msg=$($json.msg)" }
  } catch [System.Net.WebException] {
    $re = $_.Exception.Response
    if ($re) { $rs=New-Object System.IO.StreamReader($re.GetResponseStream()); "attempt $i => HTTP $($re.StatusCode.value__) $($rs.ReadToEnd())" } else { "attempt $i => $($_.Exception.Message)" }
  }
  Start-Sleep -Seconds 1
}

$base = "http://localhost:8091"
$h = @{ 'zhi-project-id' = 'suzhufang'; 'Content-Type' = 'application/json' }
$phone = "13812345678"
$idTail = "1234"
$smsCode = "123456"

# 1) captcha
$uuid = $null
for ($i=1; $i -le 4 -and -not $uuid; $i++) {
  try {
    $r = Invoke-WebRequest -Uri ($base+"/api/v3.0/portal/appLogin/captcha") -Method POST -Headers $h -Body '{}' -TimeoutSec 10 -UseBasicParsing
    $j = $r.Content | ConvertFrom-Json
    if ($j.code -eq 200) { $uuid = $j.data.uuid; "captcha OK uuid=$uuid" } else { "captcha attempt $i code=$($j.code) msg=$($j.msg)"; Start-Sleep 1 }
  } catch { "captcha attempt $i ERR $($_.Exception.Message)"; Start-Sleep 1 }
}
if (-not $uuid) { "ABORT: no captcha uuid"; exit }

# 2) send sms (format-valid dummy captchaCode)
$captchaCode = "1234"
$smsBody = @{ phone=$phone; idNumberSuffix=$idTail; captchaUuid=$uuid; captchaCode=$captchaCode } | ConvertTo-Json -Compress
try {
  $r = Invoke-WebRequest -Uri ($base+"/api/v3.0/portal/appLogin/sms") -Method POST -Headers $h -Body $smsBody -TimeoutSec 10 -UseBasicParsing
  $j = $r.Content | ConvertFrom-Json
  "sms => code=$($j.code) msg=$($j.msg)"
} catch [System.Net.WebException] {
  $resp=$_.Exception.Response
  if($resp){$sr=New-Object System.IO.StreamReader($resp.GetResponseStream());"sms HTTP $($resp.StatusCode.value__) $($sr.ReadToEnd())"}else{"sms ERR $($_.Exception.Message)"}
}

# 3) login
$loginBody = @{ phone=$phone; idNumberSuffix=$idTail; smsCode=$smsCode } | ConvertTo-Json -Compress
$token = $null
try {
  $r = Invoke-WebRequest -Uri ($base+"/api/v3.0/portal/appLogin/login") -Method POST -Headers $h -Body $loginBody -TimeoutSec 10 -UseBasicParsing
  $j = $r.Content | ConvertFrom-Json
  "login => code=$($j.code) msg=$($j.msg)"
  if ($j.code -eq 200) { $token = $j.data.token; "token=$($token.Substring(0,[Math]::Min(20,$token.Length)))..." }
} catch [System.Net.WebException] {
  $resp=$_.Exception.Response
  if($resp){$sr=New-Object System.IO.StreamReader($resp.GetResponseStream());"login HTTP $($resp.StatusCode.value__) $($sr.ReadToEnd())"}else{"login ERR $($_.Exception.Message)"}
}

# 4) apps
if ($token) {
  $ah = @{ 'zhi-project-id'='suzhufang'; 'Authorization'="Bearer $token"; 'Content-Type'='application/json' }
  try {
    $r = Invoke-WebRequest -Uri ($base+"/api/v3.0/portal/appLogin/apps") -Method POST -Headers $ah -TimeoutSec 10 -UseBasicParsing
    $j = $r.Content | ConvertFrom-Json
    "apps => code=$($j.code) msg=$($j.msg) count=$(if($j.data){$j.data.Count}else{0})"
    if ($j.data) { $j.data | ConvertTo-Json -Depth 4 -Compress }
  } catch [System.Net.WebException] {
    $resp=$_.Exception.Response
    if($resp){$sr=New-Object System.IO.StreamReader($resp.GetResponseStream());"apps HTTP $($resp.StatusCode.value__) $($sr.ReadToEnd())"}else{"apps ERR $($_.Exception.Message)"}
  }
} else { "ABORT: no token, skip apps" }
